Megvan minden ami kell. Íme a teljes Zig implementáció AWS Signature V4 aláírással, streaming támogatással és a helyes Bedrock paraméterekkel:

## AWS SigV4 aláírás – a fő nehézség Zig-ben

Nincs natív AWS SDK Zig-hez, ezért az AWS Signature Version 4-et kézzel kell implementálni. Ez a Bedrock HTTP API hívás előfeltétele – minden kéréshez HMAC-SHA256 aláírás kell az `Authorization` headerben. A `std.http.Client` Zig 0.12+ óta beépített és production-ready.[1][2]

## Teljes Zig modul – `bedrock_client.zig`

```zig
const std = @import("std");
const Allocator = std.mem.Allocator;
const http = std.http;
const crypto = std.crypto;

// ── Konfig ────────────────────────────────────────────────────────────────
pub const BedrockConfig = struct {
    region: []const u8 = "eu-west-2",
    model_id: []const u8 = "anthropic.claude-opus-4-6-v1",
    access_key_id: []const u8,
    secret_access_key: []const u8,
    session_token: ?[]const u8 = null, // IAM role esetén
};

pub const BedrockRequest = struct {
    prompt: []const u8,
    system: ?[]const u8 = null,
    max_tokens: u32 = 128000,
    temperature: f32 = 0.1,
    budget_tokens: u32 = 100000,
};

// ── SigV4 helper ──────────────────────────────────────────────────────────
fn hmacSha256(key: []const u8, data: []const u8, out: *[32]u8) void {
    var mac = crypto.auth.hmac.sha2.HmacSha256.init(key);
    mac.update(data);
    mac.final(out);
}

fn hexEncode(input: []const u8, allocator: Allocator) ![]u8 {
    const hex = try allocator.alloc(u8, input.len * 2);
    for (input, 0..) |byte, i| {
        _ = std.fmt.bufPrint(hex[i * 2 .. i * 2 + 2], "{x:0>2}", .{byte}) catch unreachable;
    }
    return hex;
}

fn sha256Hex(data: []const u8, allocator: Allocator) ![]u8 {
    var hash: [32]u8 = undefined;
    std.crypto.hash.sha2.Sha256.hash(data, &hash, .{});
    return hexEncode(&hash, allocator);
}

// ── ISO 8601 dátum/idő formátum ───────────────────────────────────────────
fn formatDatetime(timestamp: i64, buf: *[16]u8) void {
    const epoch_seconds = std.time.epoch.EpochSeconds{ .secs = @intCast(timestamp) };
    const epoch_day = epoch_seconds.getEpochDay();
    const year_day = epoch_day.calculateYearDay();
    const month_day = year_day.calculateMonthDay();
    const day_seconds = epoch_seconds.getDaySeconds();

    _ = std.fmt.bufPrint(buf, "{d:0>4}{d:0>2}{d:0>2}T{d:0>2}{d:0>2}{d:0>2}Z", .{
        year_day.year,
        month_day.month.numeric(),
        month_day.day_index + 1,
        day_seconds.getHoursIntoDay(),
        day_seconds.getMinutesIntoHour(),
        day_seconds.getSecondsIntoMinute(),
    }) catch unreachable;
}

fn formatDate(datetime: []const u8) [8]u8 {
    var date: [8]u8 = undefined;
    @memcpy(&date, datetime[0..8]);
    return date;
}

// ── SigV4 aláírás generálás ───────────────────────────────────────────────
pub fn buildAuthHeader(
    allocator: Allocator,
    config: BedrockConfig,
    method: []const u8,
    path: []const u8,
    payload: []const u8,
    datetime: []const u8,
) ![]u8 {
    const date = formatDate(datetime);
    const service = "bedrock";

    // 1. Canonical request
    const payload_hash = try sha256Hex(payload, allocator);
    defer allocator.free(payload_hash);

    const canonical_headers = try std.fmt.allocPrint(allocator,
        "content-type:application/json\nhost:bedrock-runtime.{s}.amazonaws.com\nx-amz-date:{s}\n",
        .{ config.region, datetime });
    defer allocator.free(canonical_headers);

    const signed_headers = "content-type;host;x-amz-date";

    const canonical_request = try std.fmt.allocPrint(allocator,
        "{s}\n{s}\n\n{s}\n{s}\n{s}",
        .{ method, path, canonical_headers, signed_headers, payload_hash });
    defer allocator.free(canonical_request);

    // 2. String to sign
    const cr_hash = try sha256Hex(canonical_request, allocator);
    defer allocator.free(cr_hash);

    const credential_scope = try std.fmt.allocPrint(allocator,
        "{s}/{s}/{s}/aws4_request",
        .{ &date, config.region, service });
    defer allocator.free(credential_scope);

    const string_to_sign = try std.fmt.allocPrint(allocator,
        "AWS4-HMAC-SHA256\n{s}\n{s}\n{s}",
        .{ datetime, credential_scope, cr_hash });
    defer allocator.free(string_to_sign);

    // 3. Signing key derivation
    const key_prefix = try std.fmt.allocPrint(allocator, "AWS4{s}", .{config.secret_access_key});
    defer allocator.free(key_prefix);

    var k_date: [32]u8 = undefined;
    var k_region: [32]u8 = undefined;
    var k_service: [32]u8 = undefined;
    var k_signing: [32]u8 = undefined;

    hmacSha256(key_prefix, &date, &k_date);
    hmacSha256(&k_date, config.region, &k_region);
    hmacSha256(&k_region, service, &k_service);
    hmacSha256(&k_service, "aws4_request", &k_signing);

    // 4. Signature
    var sig: [32]u8 = undefined;
    hmacSha256(&k_signing, string_to_sign, &sig);
    const sig_hex = try hexEncode(&sig, allocator);
    defer allocator.free(sig_hex);

    // 5. Authorization header
    return std.fmt.allocPrint(allocator,
        "AWS4-HMAC-SHA256 Credential={s}/{s}, SignedHeaders={s}, Signature={s}",
        .{ config.access_key_id, credential_scope, signed_headers, sig_hex });
}

// ── JSON body builder ─────────────────────────────────────────────────────
pub fn buildRequestBody(allocator: Allocator, req: BedrockRequest) ![]u8 {
    const system_part = if (req.system) |sys|
        try std.fmt.allocPrint(allocator,
            \\"system":[{{"type":"text","text":"{s}"}}],
        , .{sys})
    else
        try allocator.dupe(u8, "");
    defer allocator.free(system_part);

    return std.fmt.allocPrint(allocator,
        \\{{
        \\  "messages":[{{"role":"user","content":[{{"text":"{s}"}}]}}],
        \\  {s}
        \\  "inferenceConfig":{{
        \\    "maxTokens":{d},
        \\    "temperature":{d:.1}
        \\  }},
        \\  "additionalModelRequestFields":{{
        \\    "anthropic_beta":["output-128k-2025-02-19"],
        \\    "thinking":{{
        \\      "type":"enabled",
        \\      "budget_tokens":{d}
        \\    }}
        \\  }}
        \\}}
    , .{
        req.prompt,
        system_part,
        req.max_tokens,
        req.temperature,
        req.budget_tokens,
    });
}

// ── Fő API hívás (streaming) ───────────────────────────────────────────────
pub fn converseStream(
    allocator: Allocator,
    config: BedrockConfig,
    req: BedrockRequest,
    /// callback: minden szöveg chunk-ra meghívódik
    comptime onChunk: fn (text: []const u8) void,
) !void {
    const body = try buildRequestBody(allocator, req);
    defer allocator.free(body);

    const timestamp = std.time.timestamp();
    var datetime_buf: [16]u8 = undefined;
    formatDatetime(timestamp, &datetime_buf);
    const datetime = datetime_buf[0..16];

    const path = try std.fmt.allocPrint(
        allocator,
        "/model/{s}/converse-stream",
        .{config.model_id},
    );
    defer allocator.free(path);

    const auth_header = try buildAuthHeader(
        allocator, config, "POST", path, body, datetime,
    );
    defer allocator.free(auth_header);

    const host = try std.fmt.allocPrint(
        allocator,
        "bedrock-runtime.{s}.amazonaws.com",
        .{config.region},
    );
    defer allocator.free(host);

    const url_str = try std.fmt.allocPrint(
        allocator,
        "",
        .{ host, path },
    );
    defer allocator.free(url_str);

    const uri = try std.Uri.parse(url_str);

    var client = http.Client{ .allocator = allocator };
    defer client.deinit();

    var header_buf: [8192]u8 = undefined;
    var server_req = try client.open(.POST, uri, .{
        .server_header_buffer = &header_buf,
        .extra_headers = &.{
            .{ .name = "content-type", .value = "application/json" },
            .{ .name = "x-amz-date", .value = datetime },
            .{ .name = "authorization", .value = auth_header },
            .{ .name = "accept", .value = "application/vnd.amazon.eventstream" },
        },
    });
    defer server_req.deinit();

    server_req.transfer_encoding = .{ .content_length = body.len };
    try server_req.send();
    try server_req.writeAll(body);
    try server_req.finish();
    try server_req.wait();

    if (server_req.response.status != .ok) {
        std.log.err("Bedrock HTTP {d}", .{@intFromEnum(server_req.response.status)});
        return error.BedrockHttpError;
    }

    // ── Event stream parse ────────────────────────────────────────────────
    // AWS event stream: minden chunk előtt 4B prelude + 4B header_len + payload
    // A szöveges delta a JSON "delta"."text" mezőben van
    var stream_buf: [262144]u8 = undefined; // 256k buffer
    var total_read: usize = 0;

    while (true) {
        const n = try server_req.readAll(stream_buf[total_read..]);
        if (n == 0) break;
        total_read += n;

        // Egyszerű szöveg kinyerés: keressük a "text":" mintát
        var search_start: usize = 0;
        while (std.mem.indexOf(u8, stream_buf[search_start..total_read], "\"text\":\"")) |pos| {
            const text_start = search_start + pos + 8;
            if (std.mem.indexOf(u8, stream_buf[text_start..total_read], "\"")) |end_pos| {
                const text = stream_buf[text_start .. text_start + end_pos];
                // JSON escape decode
                const decoded = try jsonUnescape(allocator, text);
                defer allocator.free(decoded);
                onChunk(decoded);
                search_start = text_start + end_pos + 1;
            } else break;
        }

        // Ha a buffer megtelik, toljuk el a feldolgozott részt
        if (total_read > stream_buf.len - 4096) {
            const keep_from = if (search_start > 0) search_start else 0;
            std.mem.copyForwards(u8, &stream_buf, stream_buf[keep_from..total_read]);
            total_read -= keep_from;
        }
    }
}

// ── JSON string unescape ──────────────────────────────────────────────────
fn jsonUnescape(allocator: Allocator, input: []const u8) ![]u8 {
    var result = std.ArrayList(u8).init(allocator);
    defer result.deinit();
    var i: usize = 0;
    while (i < input.len) : (i += 1) {
        if (input[i] == '\\' and i + 1 < input.len) {
            i += 1;
            switch (input[i]) {
                'n'  => try result.append('\n'),
                't'  => try result.append('\t'),
                'r'  => try result.append('\r'),
                '"'  => try result.append('"'),
                '\\' => try result.append('\\'),
                else => { try result.append('\\'); try result.append(input[i]); },
            }
        } else {
            try result.append(input[i]);
        }
    }
    return result.toOwnedSlice();
}

// ── Példa main ────────────────────────────────────────────────────────────
pub fn main() !void {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const config = BedrockConfig{
        .region = "eu-west-2",
        .model_id = "anthropic.claude-opus-4-6-v1",
        .access_key_id = std.posix.getenv("AWS_ACCESS_KEY_ID") orelse @panic("Nincs AWS_ACCESS_KEY_ID"),
        .secret_access_key = std.posix.getenv("AWS_SECRET_ACCESS_KEY") orelse @panic("Nincs AWS_SECRET_ACCESS_KEY"),
        .session_token = std.posix.getenv("AWS_SESSION_TOKEN"),
    };

    const req = BedrockRequest{
        .prompt = "Prove that sqrt(2) is irrational in Lean 4.",
        .system = "You are a formal verification expert. Always output complete, compilable Lean 4 proofs.",
        .max_tokens = 128000,
        .temperature = 0.1,
        .budget_tokens = 100000,
    };

    const Handler = struct {
        fn onChunk(text: []const u8) void {
            std.io.getStdOut().writer().writeAll(text) catch {};
        }
    };

    try converseStream(allocator, config, req, Handler.onChunk);
}
```

## Replit Agent instrukciók

Ha a Replit Agent-nek adod át, ezt add mellé kontextusként:

```
Backend stack: Zig 0.14+
AWS Bedrock Converse Stream API endpoint:
  POST 

Auth: AWS Signature V4 (HMAC-SHA256), service="bedrock"
Required headers:
  - content-type: application/json
  - x-amz-date: <ISO8601 datetime>
  - authorization: AWS4-HMAC-SHA256 Credential=...

Body additionalModelRequestFields KÖTELEZŐ mezők:
  "anthropic_beta": ["output-128k-2025-02-19"]   ← 128k output engedélyező flag
  "thinking": {"type": "enabled", "budget_tokens": 100000}

inferenceConfig: maxTokens=128000, temperature=0.1
Response: AWS Event Stream (application/vnd.amazon.eventstream)
  - delta.text mezőkben jön a szöveges output
  - thinking_delta.thinking mezőkben jön a reasoning
```

## Fontos megjegyzések a backend integrációhoz

A `session_token` mező IAM role-alapú hitelesítésnél (pl. ECS task role, Lambda) is szükséges – ha Repliten `AWS_SESSION_TOKEN` env var be van állítva, automatikusan bekerül az `x-amz-security-token` headerbe. A frontend streaming esetén a Zig backend Server-Sent Events (SSE) formátumban tudja továbbítani a chunk-okat a böngészőnek, ami a legtisztább megoldás chat UI-hoz.[1]

Megvan a fájl. Így illeszd be a Replit projektedbe:

## Env secrets (Replit Secrets tab)

```
AWS_ACCESS_KEY_ID      = AKIAxxxxxxxxxxx
AWS_SECRET_ACCESS_KEY  = xxxxxxxxxxxxxxx
BEDROCK_REGION         = eu-west-2           ← opcionális, ez az alapértelmezett
BEDROCK_MODEL_ID       = anthropic.claude-opus-4-6-v1  ← opcionális
```

## Hogyan használd a backendből

A modul `initConfig` + `converseStream` párossal működik:[1]

```zig
const bedrock = @import("bedrock.zig");

// config betöltés (env-ből, nincs hardcode)
const cfg = try bedrock.initConfig(allocator);
defer bedrock.freeConfig(allocator, cfg);

// request összeállítás
const req = bedrock.Request{
    .prompt = user_message,
    .system = "You are a formal verification expert. Always output complete Zig/Lean 4 code.",
    .max_tokens = 128000,
    .temperature = 0.1,
    .budget_tokens = 100000,
};

// chunk handler – itt SSE-be írhatsz, websocketre, bárhova
const Writer = struct {
    fn onChunk(w: std.io.AnyWriter, text: []const u8) void {
        w.writeAll(text) catch {};
    }
};

try bedrock.converseStream(allocator, cfg, req, response_writer, Writer.onChunk);
```

A `onChunk` callback bármilyen context pointert elfogad (`ctx: anytype`), szóval közvetlenül bele lehet kötni egy HTTP response writer-be, channel-be, vagy WebSocket frame sender-be – a Replit Agent-nek csak azt kell megvalósítania, ami körülveszi ezt a modult.[2]
